// The pipeline uses this contract for both typed and transcribed turns.
// Evidence is data supplied for the current mode, never generated by the model.
const personal = /\b(?:prefer|like|love|enjoy|dislike|hate|avoid|cannot|can't|need|travel(?:ing|ling) with|went with|last trip)\b/i;
